<?php
$escape = static fn(mixed $value): string => htmlspecialchars((string) (is_scalar($value) ? $value : ''), ENT_QUOTES, 'UTF-8');
$filters = is_array($filters ?? null) ? $filters : [];
$page = is_array($page ?? null) ? $page : ['items' => [], 'total' => 0, 'page' => 1, 'pages' => 1];
$url = static fn(int $number): string => '/developer/academic-review?' . http_build_query(array_filter($filters + ['page_num' => $number], static fn(mixed $value): bool => is_scalar($value) && (string) $value !== ''));
$boards = $subjects = [];
foreach (($scopeOptions ?? []) as $scope) { $boards[(string) $scope['board_id']] = (string) $scope['board_id']; $subjects[(string) $scope['subject_id']] = (string) $scope['subject_id']; }
?>
<section class="page-header"><div><p class="eyebrow">Developer Question Repository · restricted reviewer workbench</p><h1>Academic review</h1><p>Work only within explicitly authorized board and subject scopes. Decisions are attributed to your authenticated account and tied to an exact proposal version.</p></div><a class="button secondary" href="/question-editor?proposal_batch=695">Proposal inventory</a></section>
<section class="card"><p><strong>Human review only.</strong> B695 proposals remain noncanonical until a qualified reviewer approves the exact version and a separately authorized person confirms an individual import.</p><p><?= (int) $page['total'] ?> in-scope proposals · Page <?= (int) $page['page'] ?> of <?= (int) $page['pages'] ?></p></section>
<form class="filter-bar" method="get" action="/developer/academic-review">
    <label for="review-search">Search proposal ID or question text</label><input id="review-search" class="field-control" type="search" name="search" value="<?= $escape($filters['search'] ?? '') ?>">
    <label for="review-board">Board</label><select id="review-board" class="field-control" name="board"><option value="">All authorized boards</option><?php foreach ($boards as $id): ?><option value="<?= $escape($id) ?>"<?= ($filters['board'] ?? '') === $id ? ' selected' : '' ?>><?= $escape($id) ?></option><?php endforeach; ?></select>
    <label for="review-subject">Subject</label><select id="review-subject" class="field-control" name="subject"><option value="">All authorized subjects</option><?php foreach ($subjects as $id): ?><option value="<?= $escape($id) ?>"<?= ($filters['subject'] ?? '') === $id ? ' selected' : '' ?>><?= $escape($id) ?></option><?php endforeach; ?></select>
    <label for="review-status">Academic status</label><select id="review-status" class="field-control" name="status"><option value="">All states</option><?php foreach (['PENDING_REVIEW','ASSIGNED','IN_REVIEW','REVISION_REQUESTED','APPROVED','REJECTED','DEFERRED'] as $state): ?><option value="<?= $state ?>"<?= strtoupper((string) ($filters['status'] ?? '')) === $state ? ' selected' : '' ?>><?= str_replace('_', ' ', $state) ?></option><?php endforeach; ?></select>
    <label for="review-assigned">Assignment</label><select id="review-assigned" class="field-control" name="assigned"><option value="">Any assignment</option><option value="mine"<?= ($filters['assigned'] ?? '') === 'mine' ? ' selected' : '' ?>>Assigned to me</option><option value="unassigned"<?= ($filters['assigned'] ?? '') === 'unassigned' ? ' selected' : '' ?>>Unassigned</option></select>
    <button type="submit">Apply filters</button>
</form>
<?php if (($page['items'] ?? []) === []): ?><p class="empty-state">No proposals match your authorized scopes and filters.</p><?php else: ?><div class="proposal-list">
<?php foreach ($page['items'] as $row): $proposal = (array) ($row['proposal'] ?? []); $workflow = (array) ($row['workflow'] ?? []); $question = (array) ($proposal['proposed_question'] ?? []); ?>
<article class="card proposal-item" data-proposal-id="<?= $escape($proposal['id'] ?? '') ?>"><h2>Proposal #<?= $escape($proposal['question_id'] ?? '') ?></h2><p><strong><?= $escape(str_replace('_', ' ', (string) ($workflow['state'] ?? 'PENDING_REVIEW'))) ?></strong> · Noncanonical · Not available in learner pools</p><p><strong>Board:</strong> <?= $escape($proposal['board_name'] ?? $proposal['board_id'] ?? '') ?> · <strong>Subject:</strong> <?= $escape($proposal['subject_name'] ?? $proposal['subject_id'] ?? '') ?></p><p><?= $escape($question['stem'] ?? '') ?></p><?php if (!empty($workflow['assigned_reviewer_id'])): ?><p>Assigned reviewer account: <?= $escape($workflow['assigned_reviewer_id']) ?></p><?php endif; ?><a class="button" href="/developer/academic-review/proposal?id=<?= rawurlencode((string) ($proposal['id'] ?? '')) ?>">Open complete proposal and review history</a></article>
<?php endforeach; ?></div><?php endif; ?>
<nav class="pagination" aria-label="Academic review proposal pages"><span>Showing <?= count($page['items'] ?? []) ?> of <?= (int) $page['total'] ?> · Page <?= (int) $page['page'] ?> of <?= (int) $page['pages'] ?></span><div class="page-actions"><?php if ((int) $page['page'] > 1): ?><a class="button button-outline" rel="prev" href="<?= $escape($url((int) $page['page'] - 1)) ?>">Previous</a><?php endif; ?><?php if ((int) $page['page'] < (int) $page['pages']): ?><a class="button button-outline" rel="next" href="<?= $escape($url((int) $page['page'] + 1)) ?>">Next</a><?php endif; ?></div></nav>
